// Generated by `just generate` from `src/plugins/claudetto/slices/setup/domain/commit-hook.ts`. Edit the source and run `just generate`.
// The `env` keys of the settings that put the attribution check in every git commit of the Bash tool.
// Git 2.54 and later reads `GIT_CONFIG_COUNT`, `GIT_CONFIG_KEY_<n>`, and `GIT_CONFIG_VALUE_<n>` from the environment,
// and a config-based hook (`hook.<name>.event` and `hook.<name>.command`) runs next to the hooks of the repository.
// Two `enabled` keys in the same scope make the command scope win over a repository that turns the hook or the event off.
// The keys of the user stay, and the keys of claudetto go after them, so a second run changes nothing.
// This file is in the import graph of the hooks module through `settings.ts`, so it has no `node:` import.

import { HOOK_NAME, hookScript } from "../../../kernel/commit-hook/index.ts";
import {
  PUSH_HOOK_NAME,
  pushHookScript,
} from "../../../kernel/push-hook/index.ts";
import { isObject } from "./merge.ts";
import type { Change, Json } from "./types.ts";

/**
 * The config pairs of the hook, in slot order.
 * The `enabled` pairs make the command scope win over a repository that sets `hook.<name>.enabled`, `hook.commit-msg.enabled`, or `hook.pre-push.enabled` to false.
 * The second hook is the `pre-push` check of the AI policy.
 */
const PAIRS = (script: string, pushScript: string): [string, string][] => [
  [`hook.${HOOK_NAME}.event`, "commit-msg"],
  [`hook.${HOOK_NAME}.command`, script],
  [`hook.${HOOK_NAME}.enabled`, "true"],
  ["hook.commit-msg.enabled", "true"],
  [`hook.${PUSH_HOOK_NAME}.event`, "pre-push"],
  [`hook.${PUSH_HOOK_NAME}.command`, pushScript],
  [`hook.${PUSH_HOOK_NAME}.enabled`, "true"],
  ["hook.pre-push.enabled", "true"],
];

/** The count in `env`, or 0 when it is missing or not a count. */
const countOf = (env: Json): number => {
  const n = Number.parseInt(String(env["GIT_CONFIG_COUNT"] ?? ""), 10);
  return Number.isInteger(n) && n > 0 ? n : 0;
};

/** The index of the config key `name` among the first `count` keys of `env`, or -1. */
const indexOf = (env: Json, count: number, name: string): number => {
  for (let i = 0; i < count; i++)
    if (env[`GIT_CONFIG_KEY_${i}`] === name) return i;
  return -1;
};

/**
 * `current` with the commit hook of claudetto in `env`, and one change line for each key that differs.
 * Each pair takes the slot that it took before, or the first free slot after the keys of the user.
 */
export const planCommitHook = (current: Json, changes: Change[]): Json => {
  const env: Json = isObject(current["env"]) ? { ...current["env"] } : {};
  const count = countOf(env);
  const next: Json = { ...env };
  let total = count;
  const scripts = new Set<string>();
  for (const [key, value] of PAIRS(hookScript(), pushHookScript())) {
    const found = indexOf(env, count, key);
    const slot = found < 0 ? total++ : found;
    if (key.endsWith(".command")) scripts.add(`GIT_CONFIG_VALUE_${slot}`);
    next[`GIT_CONFIG_KEY_${slot}`] = key;
    next[`GIT_CONFIG_VALUE_${slot}`] = value;
  }
  next["GIT_CONFIG_COUNT"] = String(total);
  const show = (key: string, value: unknown) => {
    if (value === undefined) return "(unset)";
    return scripts.has(key) ? "(a hook script)" : JSON.stringify(value);
  };
  for (const key of new Set([...Object.keys(env), ...Object.keys(next)]))
    if (env[key] !== next[key])
      changes.push({
        key: `env.${key}`,
        line: `env.${key}: ${show(key, env[key])} -> ${show(key, next[key])}`,
      });
  return { ...current, env: next };
};
